-- A workspace state.db written by kanso 0.7.0, as `sqlite3 state.db .dump` recorded it.
--
-- Produced on 2026-09-17 on macOS arm64 by driving the README demo sequence with the
-- v0.7.0 checkout (`kanso --version` printing 0.7.0) in a fresh workspace: `kanso init
-- --demo`, `data load --loader synthetic --spec demo.yaml`, `data instruments resolve
-- --as-of 2024-01-02`, `data snapshot`, `hyp add hypotheses/demo_mr/hypothesis.yaml`,
-- `classify demo_mr`, `research run demo_mr --cards 3`, `research end demo_mr`. It holds
-- one hypothesis, one run, four cards (the baseline and the demo's keep, discard and crash), seven blobs,
-- thirteen events and four ledgered model calls, and is stamped PRAGMA user_version = 2,
-- the newest migration 0.7.0 shipped. The paths inside it are the ones that machine used.
--
-- The suite rebuilds a database from this script and applies every migration the package
-- ships after version 2 over it, so a migration that cannot run over a populated earlier
-- workspace fails here before it is released. Nothing in it is edited by hand; a later
-- release that needs a newer starting point records a new dump beside this one.
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE blobs (
    sha        TEXT    NOT NULL PRIMARY KEY,
    data       BLOB    NOT NULL,
    size       INTEGER NOT NULL,
    created_at TEXT    NOT NULL
);
